mapper.select:
SELECT *
FROM teaching_task
WHERE status = 'RUNNING'
  AND lease_expire_at < #{now}
ORDER BY lease_expire_at ASC
LIMIT #{limit}

mapper.update:
UPDATE teaching_task
SET status = 'RETRYING',
    lease_owner = NULL,
    lease_token = NULL,
    lease_expire_at = NULL,
    last_error = 'lecture task lease expired',
    updated_at = #{now}
WHERE task_id = #{taskId}
  AND status = 'RUNNING'
  AND lease_token = #{leaseToken}
  AND lease_expire_at < #{now}

mapper.select:
SELECT COUNT(1)
FROM teaching_task
WHERE task_id = #{taskId}
  AND status = 'RUNNING'
  AND lease_token = #{leaseToken}

mapper.update:
UPDATE teaching_task
SET response_json = #{responseJson},
    current_stage = #{currentStage},
    updated_at = #{updatedAt}
WHERE task_id = #{taskId}
  AND status = 'RUNNING'
  AND lease_token = #{leaseToken}
